    def unit_of_work_dec(func):
        @wraps(func)
        def unit_of_work_wrapper(*args, **kwargs):
            tx = py2neo.cypher.get_current_tx()
            if timeout is not None:
                tx.timeout = timeout
            if metadata is not None:
                tx.metadata = metadata
            try:
                return func(*args, **kwargs)
            except py2neo.cypher.TransactionTimeoutException:
                raise TimeoutError(f"Transaction timeout in {func.__name__}")
            except py2neo.cypher.TransactionException:
                raise RuntimeError(f"Transaction error for {func.__name__}")
        return unit_of_work_wrapper
    return unit_of_work_dec

