def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = dict()
        stats = {'hits': 0, 'misses': 0}

        def memoized(*args):
            if not typed and len(args) == 1 and isinstance(args[0], tuple):
                args = args[0]
            key = args
            try:
                if key in cache:
                    stats['hits'] += 1
                    return cache[key]
                else:
                    stats['misses'] += 1
                    value = func(*args)
                    cache[key] = value
                    return value
            except KeyError:
                pass
            except TypeError:
                pass

        memoized.cache = cache
        memoized.stats = stats
        memoized.reset = lambda: cache.clear()
        return memoized

    return decorator
```
