def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    # Initialize an empty dictionary to store the merged nodes
    merged_nodes = {}

    # Iterate over the given nodes
    for node in nodes:
        # If the node key is not already in the dictionary, add it with its value
        if node[0] not in merged_nodes:
            merged_nodes[node[0]] = node[1]
        # If the node key is already in the dictionary and the corresponding value is a mapping node, deep merge the values
        elif isinstance(merged_nodes[node[0]], MappingNode):
            merged_nodes[node[0]] = deep_merge_dictionaries(merged_nodes[node[0]].value, node[1].value)
        # If the node key is already in the dictionary and the corresponding value is not a mapping node, overwrite the value
        else:
            merged_nodes[node[0]] = node[1]

    # Return the merged nodes
    return list(merged_nodes.items())

