def get_spec_defaults(self, spec, *args, **kwargs):
    # Resolve arguments' values from spec and other sources
    defaults = {}
    for param in spec.parameters.values():
        # Check if parameter has default value
        if param.default is not NO_DEFAULT_VALUE:
            defaults[param.name] = argparse.namespace(param.default)
        # Check if parameter has a default factory
        elif param.default_factory is not None:
            defaults[param.name] = param.default_factory()
        # Check if parameter has a type
        elif param.type is not None:
            defaults[param.name] = argparse.namespace(param.type)
        # Check if parameter has an annotation
        elif param.annotation is not None:
            defaults[param.name] = param.annotation
        # If all else fails, set default value to None
        else:
            defaults[param.name] = None

    # Merge defaults with other keyword arguments
    for name, value in kwargs.items():
        defaults[name] = value

    # Return resolved defaults
    return defaults

