    try:
        result = subprocess.run(ansible_args, check=True, encoding="utf-8")
        return json.loads(result.stdout)
    except subprocess.CalledProcessError as e:
        raise ValueError("Ansible command failed with error: {}".format(e))
    except json.JSONDecodeError as e:
        raise ValueError("Unable to parse Ansible command output: {}".format(e))
