def _convert_non_cli_args(self, parser_name, values_dict):
    values_dict_copy = values_dict.copy()
    for arg in values_dict_copy:
        # Check that the argument is not a boolean
        if values_dict_copy[arg] != "true" and values_dict_copy[arg] != "false":
            # Check that the argument is not a list
            if values_dict_copy[arg].startswith("[") and values_dict_copy[arg].endswith("]"):
                values_dict_copy[arg] = values_dict_copy[arg][1:-1].split(",")
            else:
                # Try to cast to int
                try:
                    values_dict_copy[arg] = int(values_dict_copy[arg])
                except ValueError:
                    # Try to cast to float
                    try:
                        values_dict_copy[arg] = float(values_dict_copy[arg])
                    except ValueError as e:
                        # Check if the argument is a bool
                        if values_dict_copy[arg].lower() == "true":
                            values_dict_copy[arg] = True
                        elif values_dict_copy[arg].lower() == "false":
                            values_dict_copy[arg] = False
                        else:
                            # Set the argument to its original value
                            values_dict_copy[arg] = values_dict_copy[arg]
    return values_dict_copy
